			function formatingPhoneNo(phoneNo) {
			    var result;
			    if (phoneNo.length == 11) {
			        result = phoneNo.substr(0, 3) + "-" + phoneNo.substr(3, 4) + "-" + phoneNo.substr(7, 4);
			    } else if (phoneNo.length == 10) {
			        if (phoneNo.substr(0, 2) == "02") {
			            result = phoneNo.substr(0, 2) + "-" + phoneNo.substr(2, 4) + "-" + phoneNo.substr(6, 4);
			        } else {
			            result = phoneNo.substr(0, 3) + "-" + phoneNo.substr(3, 3) + "-" + phoneNo.substr(6, 4);
			        }
			    } else if (phoneNo.length == 9) {
			        result = phoneNo.substr(0, 2) + "-" + phoneNo.substr(2, 3) + "-" + phoneNo.substr(5, 4);
			    } else if (phoneNo.length == 8) {
			        result = phoneNo.substr(0, 4) + "-" + phoneNo.substr(4, 4);
			    } else {
			        result = phoneNo;
			    }
			    return result;
			}

